      if (stored) {
        var parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          todoList = parsed;
          // Recover the highest id
          for (var i = 0; i < todoList.length; i++) {
            if (todoList[i].id > idCounter) idCounter = todoList[i].id;
          }
          return;
        }
      }
    } catch (e) { /* ignore */ }
    todoList = [];
  }

  function loadFilter() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY + '_filter');
      if (stored) return stored;
    } catch (e) { /* ignore */ }
    return '';
  }

  function saveFilter(f) {
    localStorage.setItem(STORAGE_KEY + '_filter', f);
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todoList));
  }

  function saveFilter(filter) {
    try {
      if (filter === 'all') {
